corrected_code:
oauth_router = APIRouter(prefix="/users/{user_id}/oauth", tags=["oauth-management"])

@oauth_router.delete("/{oauth_network}")
async def unlink_oauth_account(
    user_id: uuid.UUID,
    oauth_network: str,
    user_manager: BaseUserManager = Depends(get_user_manager),
    current_user: User = Depends(current_active_user)
):
    if current_user.id != user_id and not current_user.is_superuser:
        raise HTTPException(status_code=403, detail="Forbidden: cannot manage OAuth bindings for another user")

    target_user = await user_manager.get(user_id)
    if not target_user:
        raise HTTPException(status_code=404, detail="User not found")

    matching_accounts = [acc for acc in target_user.oauth_accounts if acc.oauth_name == oauth_network]
    if not matching_accounts:
        raise HTTPException(status_code=404, detail="OAuth provider binding not found")

    for acc in matching_accounts:
        await user_manager.user_db.delete_oauth_account(target_user, acc)

    return {"status": "unlinked", "provider": oauth_network}
